#!/bin/sh
# DJAEGER read-only privileged investigator. Fixed local probes only; never executes model-supplied commands.
INV_DIR=/root/djaeger-modem/investigator; INV_FILE=$INV_DIR/evidence.txt; mkdir -p "$INV_DIR"; chmod 700 "$INV_DIR" 2>/dev/null
redact(){ sed -r 's/[0-9]{14,20}/[REDACTED_ID]/g; s/([A-Fa-f0-9]{2}:){5}[A-Fa-f0-9]{2}/[REDACTED_MAC]/g; s/(api[_ -]?key|authorization|cookie|session|token|password|passwd|secret|imei|imsi|iccid|serial)["'"'"'=: ]+["'"'"']?[^ ,;"'"'"']+/\1=[REDACTED]/Ig; s/(x-goog-api-key|__RequestVerificationToken)["'"'"'=: ]+[^ ,;"'"'"']+/\1=[REDACTED]/Ig'; }
service_state(){ S="$1"; if [ -x "/etc/init.d/$S" ]; then "/etc/init.d/$S" status >/dev/null 2>&1 && echo "$S=running" || echo "$S=installed_not_running"; else echo "$S=not_installed"; fi; }
investigator_collect(){ T="$INV_FILE.tmp"; : > "$T"; { echo '[SYSTEM]'; uname -a; uptime; free 2>/dev/null; df -h 2>/dev/null | head -n 20; echo '[NETWORK]'; ip addr 2>/dev/null; ip route 2>/dev/null; ip rule 2>/dev/null; echo '[WAN_UBUS]'; ubus call network.interface.wan status 2>/dev/null; echo '[LINK_STATS]'; ip -s link 2>/dev/null; echo '[CONNTRACK]'; cat /proc/sys/net/netfilter/nf_conntrack_count 2>/dev/null; cat /proc/sys/net/netfilter/nf_conntrack_max 2>/dev/null; echo '[SERVICES]'; service_state dnsmasq; service_state odhcpd; service_state firewall; service_state openclash; service_state AdGuardHome; echo '[USB]'; for d in /sys/bus/usb/devices/*; do [ -f "$d/idVendor" ] || continue; printf '%s vendor=%s product=%s\n' "$(basename "$d")" "$(cat "$d/idVendor" 2>/dev/null)" "$(cat "$d/idProduct" 2>/dev/null)"; done; echo '[KERNEL_RECENT]'; dmesg 2>/dev/null | tail -n 160 | grep -Ei 'usb|wwan|cdc|eth|net|route|dns|timeout|reset|disconnect|error|fail' | tail -n 100; echo '[LOG_RECENT]'; logread 2>/dev/null | tail -n 180 | grep -Ei 'netifd|dnsmasq|odhcp|firewall|usb|wan|wwan|error|fail|timeout|restart' | tail -n 120; echo '[DJAEGER_INCIDENTS]'; tail -n 12 /root/djaeger-modem/incidents.csv 2>/dev/null; echo '[DJAEGER_RECOVERY]'; tail -n 12 /root/djaeger-modem/recovery-outcomes.csv 2>/dev/null; } | redact | cut -c1-500 > "$T"; chmod 600 "$T"; mv "$T" "$INV_FILE"; }
investigator_summary(){ investigator_collect; tr '\n' '|' < "$INV_FILE" | cut -c1-6000; }
